UPDATE settings SET value = json_set(value, '$.hero_headline_main', 'Your business is struggling.', '$.hero_headline_accent', 'Let''s change that.') WHERE key = 'home_sections';
INSERT INTO settings (key, value) VALUES ('approach_items', '[{"title": "Discover & Define", "body": "We learn how your organisation works, who it serves and where things get stuck. Together, we define what your website, software or system needs to achieve.", "icon": "Search"}, {"title": "Design & Plan", "body": "We map the user experience, data and integrations, then agree the scope, budget and delivery stages. You see the proposed direction before development starts.", "icon": "PenTool"}, {"title": "Build & Connect", "body": "We develop your website or software, connect the systems it depends on, and build AI or automation workflows where they serve a clear purpose. You review progress along the way.", "icon": "Code2"}, {"title": "Test & Refine", "body": "We test the journeys, integrations and outputs with you, including AI behaviour where relevant. We refine the work against the agreed requirements before release.", "icon": "CheckCircle2"}, {"title": "Launch & Support", "body": "We deploy, help your team get started and agree the care your solution needs. Updates, maintenance and improvements can continue as your organisation grows.", "icon": "Rocket"}]') ON CONFLICT(key) DO UPDATE SET value = excluded.value;
